<script setup lang="ts">
import {computed,onMounted,onBeforeUnmount,ref} from 'vue'
import {useRoute,onBeforeRouteLeave,onBeforeRouteUpdate} from 'vue-router'
import {ElMessageBox} from 'element-plus'
import {executionApi,projectsApi,type ExecutionTask,type ExecutionItem,type ExecutionStatus,type ExecutionEvent} from '../api'
import {errorMessage,formatDate} from '../utils'
const route=useRoute(),pid=Number(route.params.projectId),tid=String(route.params.taskId)
const task=ref<ExecutionTask>(),projectName=ref(''),loading=ref(false),error=ref(''),search=ref(''),status=ref<ExecutionStatus|'all'>('all'),completing=ref(false)
const names:Record<ExecutionStatus,string>={not_run:'未执行',passed:'通过',failed:'失败',blocked:'阻塞'}
const types={functional:'功能',boundary:'边界',exception:'异常'}
const filtered=computed(()=>task.value?.items.filter(item=>(status.value==='all'||status.value===item.status)&&`${item.snapshot.fields.title} ${item.snapshot.requirement_title} ${item.snapshot.feature_name}`.toLocaleLowerCase().includes(search.value.trim().toLocaleLowerCase()))||[])
const editor=ref(false),item=ref<ExecutionItem>(),saving=ref(false),formError=ref(''),original=ref('')
const form=ref({status:'not_run' as ExecutionStatus,actual_result:'',defect_note:''})
const dirty=computed(()=>editor.value&&JSON.stringify(form.value)!==original.value)
const historyOpen=ref(false),history=ref<ExecutionEvent[]>([]),historyLoading=ref(false),historyError=ref(''),historyTitle=ref('')
let pending:{signature:string;id:string}|undefined
async function load(){loading.value=true;error.value='';try{const[p,t]=await Promise.all([projectsApi.get(pid),executionApi.get(pid,tid)]);projectName.value=p.name;task.value=t}catch(e){error.value=errorMessage(e)}finally{loading.value=false}}
function edit(row:ExecutionItem){item.value=row;form.value={status:row.status,actual_result:row.actual_result,defect_note:row.defect_note};original.value=JSON.stringify(form.value);formError.value='';pending=undefined;editor.value=true}
function changeStatus(value:unknown){if(value==='not_run'){form.value.actual_result='';form.value.defect_note=''}}
async function discard(){if(saving.value||completing.value)return false;if(!dirty.value)return true;try{await ElMessageBox.confirm('放弃尚未保存的执行结果？','未保存的结果',{confirmButtonText:'放弃修改',cancelButtonText:'继续编辑',type:'warning'});return true}catch{return false}}
async function close(done:()=>void){if(await discard()){editor.value=false;done()}}
async function save(){if(!item.value||saving.value)return;saving.value=true;formError.value='';try{const data={...form.value,actual_result:form.value.actual_result.trim(),defect_note:form.value.defect_note.trim(),expected_revision:item.value.revision};if(data.status!=='not_run'&&!data.actual_result)throw Error('请填写实际结果或阻塞原因。');const signature=JSON.stringify(data);if(!pending||pending.signature!==signature)pending={signature,id:crypto.randomUUID()};await executionApi.save(pid,tid,item.value.id,{...data,request_id:pending.id});editor.value=false;void load()}catch(e){formError.value=errorMessage(e)+' 输入仍保留。若提交超时，请先核对任务或结果历史；相同内容重试沿用原请求标识。'}finally{saving.value=false}}
async function finish(){if(!task.value||completing.value)return;try{await ElMessageBox.confirm(`本任务 ${task.value.stats.total} 条均已记录，含失败 ${task.value.stats.failed}、阻塞 ${task.value.stats.blocked}。结束后结果锁定，是否确认？`,'结束人工执行任务',{type:'warning',confirmButtonText:'确认结束',cancelButtonText:'继续记录'})}catch{return}completing.value=true;error.value='';try{task.value=await executionApi.complete(pid,tid,task.value.revision)}catch(e){error.value=errorMessage(e)}finally{completing.value=false}}
async function showHistory(row:ExecutionItem){historyTitle.value=row.snapshot.fields.title;historyOpen.value=true;history.value=[];historyLoading.value=true;historyError.value='';try{history.value=await executionApi.history(pid,tid,row.id)}catch(e){historyError.value=errorMessage(e)}finally{historyLoading.value=false}}
function unload(event:BeforeUnloadEvent){if(dirty.value||saving.value){event.preventDefault();event.returnValue=''}}
onBeforeRouteLeave(discard);onBeforeRouteUpdate(discard);onMounted(()=>{window.addEventListener('beforeunload',unload);void load()});onBeforeUnmount(()=>window.removeEventListener('beforeunload',unload))
</script>
<template><main><router-link :to="`/projects/${pid}/execution-tasks`" class="back-link">← 执行任务列表</router-link><div class="page-heading"><div><div class="eyebrow">MANUAL EXECUTION RECORD</div><h1>{{task?.name||'执行任务'}}</h1><p>{{projectName}} · {{task?.status==='completed'?'已结束，结果已锁定':'人工执行后填写结果，保存即时生效'}}</p></div><div><el-button :loading="loading" :disabled="editor||completing" @click="load">重新加载任务</el-button><el-button v-if="task?.status==='open'" type="primary" :loading="completing" :disabled="loading||editor||!!task.stats.not_run" @click="finish">结束任务</el-button></div></div><el-alert v-if="error" :title="error" type="error" :closable="false"/>
<template v-if="task"><section class="project-panel execution-task-info"><p class="execution-text"><strong>环境 / 版本：</strong>{{task.environment}}</p><p class="execution-text"><strong>执行人：</strong>{{task.executor||'未填写'}}</p><p v-if="task.note" class="execution-text"><strong>备注：</strong>{{task.note}}</p><p class="field-help">创建 {{formatDate(task.created_at)}} · 更新 {{formatDate(task.updated_at)}}<span v-if="task.completed_at"> · 结束 {{formatDate(task.completed_at)}}</span></p><div class="execution-stats"><span>已记录 {{task.stats.recorded}} / {{task.stats.total}}</span><span>通过 {{task.stats.passed}}</span><span>失败 {{task.stats.failed}}</span><span>阻塞 {{task.stats.blocked}}</span><span>未执行 {{task.stats.not_run}}</span><span>通过率 {{task.stats.pass_rate===null?'—':`${task.stats.pass_rate}%`}}</span></div><p class="field-help">通过率 = 通过 /（通过 + 失败），当前分母 {{task.stats.pass_rate_denominator}}；阻塞和未执行不计入。仅表示本任务的人工记录。</p></section><section class="project-panel"><div class="panel-toolbar"><h2>执行快照 {{filtered.length}} / {{task.items.length}}</h2><div class="execution-filters"><el-select v-model="status" aria-label="执行状态筛选"><el-option label="所有状态" value="all"/><el-option v-for="(label,key) in names" :key="key" :value="key" :label="label"/></el-select><el-input v-model="search" placeholder="搜索快照标题、需求或功能点" clearable aria-label="搜索执行快照"/></div></div><div class="draft-panel-body"><article v-for="row in filtered" :key="row.id" class="case-card execution-item"><div class="case-card-title"><h3>{{row.position}}. {{row.snapshot.fields.title}}</h3><el-tag>{{names[row.status]}}</el-tag><span>{{row.snapshot.fields.priority}} · {{types[row.snapshot.fields.case_type]}}</span><el-tag v-if="row.snapshot.source==='mock'" type="warning">Mock 用例来源</el-tag><el-tag v-if="row.snapshot.fields.is_smoke" size="small">冒烟</el-tag></div><p class="field-help">{{row.snapshot.requirement_title}} / {{row.snapshot.module}} / {{row.snapshot.feature_name}} · 采纳版本 {{row.snapshot.review_revision}} · 结果版本 {{row.revision}}</p><p v-if="row.snapshot.outdated_at_creation" class="outdated-label">创建时依据已变化，已由创建者确认适用性。</p><dl><dt>前置条件</dt><dd>{{row.snapshot.fields.precondition||'无'}}</dd><dt>操作步骤</dt><dd><ol><li v-for="(step,index) in row.snapshot.fields.steps" :key="index">{{step}}</li></ol></dd><dt>预期结果</dt><dd>{{row.snapshot.fields.expected_result}}</dd><dt>人工实际结果</dt><dd>{{row.actual_result||'尚未记录'}}</dd><dt>缺陷 / 备注</dt><dd>{{row.defect_note||'无'}}</dd></dl><p class="field-help">{{row.recorded_at?`最近保存 ${formatDate(row.recorded_at)}`:'未保存过执行结果'}} · 快照用例 ID {{row.snapshot.case_id}}</p><el-button v-if="task.status==='open'" type="primary" plain :disabled="loading||completing" @click="edit(row)">记录结果</el-button><el-button :disabled="historyLoading" @click="showHistory(row)">结果历史</el-button><details class="execution-source"><summary>来源快照标识</summary><p>需求 ID {{row.snapshot.requirement_id}} · 生成记录 {{row.snapshot.generation_id}}</p><p>本任务不依赖来源继续存在，来源删除不改变此快照。</p></details></article><el-empty v-if="!filtered.length" description="没有匹配的执行条目"/></div></section></template>
<el-dialog v-model="editor" title="记录人工执行结果" width="min(640px,95vw)" :close-on-click-modal="false" :before-close="close"><h3>{{item?.snapshot.fields.title}}</h3><p class="field-help">请在实际环境完成操作后填写，保存不会自动执行用例或提交外部缺陷。</p><el-form :disabled="saving" label-position="top"><el-form-item label="执行状态"><el-select v-model="form.status" aria-label="结果状态" @change="changeStatus"><el-option v-for="(label,key) in names" :key="key" :value="key" :label="label"/></el-select></el-form-item><el-alert v-if="form.status==='not_run'" title="保存为未执行会清空当前实际结果和缺陷备注，既有修改历史保留。" type="info" :closable="false"/><el-form-item label="实际结果 / 阻塞原因（执行后必填）"><el-input v-model="form.actual_result" type="textarea" :rows="5" maxlength="5000" show-word-limit :disabled="form.status==='not_run'" aria-label="实际执行结果"/></el-form-item><el-form-item label="缺陷编号、地址或备注（选填，仅文本保存）"><el-input v-model="form.defect_note" type="textarea" :rows="3" maxlength="2000" :disabled="form.status==='not_run'" aria-label="缺陷备注"/></el-form-item></el-form><el-alert v-if="formError" :title="formError" type="error" :closable="false"/><template #footer><el-button :disabled="saving" @click="close(()=>editor=false)">取消</el-button><el-button type="primary" :loading="saving" :disabled="!dirty" @click="save">保存执行结果</el-button></template></el-dialog>
<el-dialog v-model="historyOpen" :title="`结果历史 · ${historyTitle}`" width="min(640px,95vw)"><p class="field-help">按版本倒序显示已保存结果；修改不覆盖旧历史。</p><el-alert v-if="historyError" :title="historyError" type="error" :closable="false"/><p v-if="historyLoading">加载中…</p><article v-for="event in history" :key="event.id" class="execution-event"><h4>版本 {{event.revision}} · {{names[event.status]}} · {{formatDate(event.created_at)}}</h4><p class="execution-text">{{event.actual_result||'未执行'}}</p><p class="execution-text">{{event.defect_note||'无缺陷备注'}}</p></article><el-empty v-if="!history.length&&!historyLoading" description="尚无结果修改记录"/></el-dialog></main></template>
<style scoped>.execution-task-info{padding:20px;margin-bottom:22px}.execution-text{white-space:pre-wrap;overflow-wrap:anywhere}.execution-stats{display:flex;gap:18px;flex-wrap:wrap;font-weight:600}.execution-filters{display:flex;gap:12px}.execution-filters .el-select{width:130px}.execution-filters .el-input{width:230px}.execution-source{margin-top:14px;font-size:12px;color:#61718a}.execution-source p{overflow-wrap:anywhere}.execution-item dd{white-space:pre-wrap;overflow-wrap:anywhere}.execution-event{border-top:1px solid #e3eaf1;padding:8px 0}</style>
